local function setFaceTexture(p1, p2) --[[ setFaceTexture | Line: 53 ]]
	p1:WaitForChild("Config")

	local BlinkingParts = p1:FindFirstChild("BlinkingParts")
	local list = {}

	if BlinkingParts and #BlinkingParts:GetChildren() > 0 then
		for i, v in ipairs(BlinkingParts:GetChildren()) do
			if v:IsA("ObjectValue") then
				table.insert(list, v.Value)

				if v.Value:FindFirstChildWhichIsA("MeshPart") then
					table.insert(list, v.Value:FindFirstChildWhichIsA("MeshPart"))
				end
			end
		end
	else
		local Head = p1:FindFirstChild("Head")

		if not Head then
			warn("No Head found in character and no BlinkingParts folder.")

			return
		end

		table.insert(list, Head)

		if Head:FindFirstChild("Head") then
			table.insert(list, Head.Head)
		end
	end

	for i, v in ipairs(list) do
		if v:IsA("BasePart") then
			v.TextureID = p2
		end
	end
end

